import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  /** Hashed with bcrypt. Absent for accounts created via an OAuth provider only. */
  passwordHash?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

/**
 * Creates a new user with an email/password credential. Throws if the email
 * is already registered.
 */
export async function createUser(
  email: string,
  name: string,
  password: string
): Promise<User> {
  const normalized = email.trim().toLowerCase();
  if (await getUserByEmail(normalized)) {
    throw new Error("A user with that email already exists.");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user: User = {
    id: String(nextId++),
    email: normalized,
    name: name.trim() || normalized,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return user;
}

/**
 * Verifies an email/password pair. Returns the user on success, or
 * undefined if the email is unknown, has no password set (OAuth-only), or
 * the password doesn't match.
 */
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const user = await getUserByEmail(email);
  if (!user?.passwordHash) return undefined;
  const ok = await bcrypt.compare(password, user.passwordHash);
  return ok ? user : undefined;
}

/**
 * Finds an existing user by email, or creates one with no password set.
 * Used for OAuth sign-in (e.g. Google), which never carries a password.
 */
export async function findOrCreateOAuthUser(
  email: string,
  name: string
): Promise<User> {
  const existing = await getUserByEmail(email);
  if (existing) return existing;
  const user: User = {
    id: String(nextId++),
    email: email.trim().toLowerCase(),
    name: name.trim() || email,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  return user;
}

